        def is_subset(a, b):
            return a|b == b

        left = [-1]*len(nums)
        stk = []
        for i in reversed(xrange(len(nums))):
            while stk and not is_proper_subset(nums[i], nums[stk[-1]]):
                left[stk.pop()] = i
