            if depth[a] < depth[b]:
                a, b = b, a
            d = depth[a]-depth[b]
            for k in xrange(len(par)):
                if d&(1<<k):
                    a = par[k][a]
            if a == b:
                return a
            for k in reversed(xrange(len(par))):
                if par[k][a] != par[k][b]:
                    a, b = par[k][a], par[k][b]
            return par[0][a]

