            if u == l:
                return 1
            d = depth[u]-depth[t]
            b, r = 1 if card == 0 else 0, 1 if card == 1 else 0
            for k in xrange(len(par)):
                if not d&(1<<k):
                    continue
                b, r = (b*cnt[k][u][BB]+r*cnt[k][u][RB])%MOD, (b*cnt[k][u][BR]+r*cnt[k][u][RR])%MOD
                u = par[k][u]
            return (b+r)%MOD

        adj = [[] for _ in xrange(n)]
        for u in xrange(n):
            if parent[u] != -1:
                adj[parent[u]].append(u)
