        cnt = [[(0,)*4 for _ in xrange(n)] for _ in xrange(ceil_log2(n-1)+1)]
        for u in xrange(n):
            par[0][u] = parent[u]
            cnt[0][u] = (gates[u][1], gates[u][2], gates[u][2], gates[u][0])
        for k in xrange(1, len(par)):
            for u in xrange(n):
                if par[k-1][u] == -1:
                    continue
                par[k][u] = par[k-1][par[k-1][u]]
                cnt[k][u] = mult(cnt[k-1][u], cnt[k-1][par[k-1][u]])
        result = 0
